#!/usr/bin/env bash
#
# regen-uki.sh - rebuild a slot's UKI in place, from inside that slot.
#
# WHY THIS EXISTS. A change to a dracut module under
# image_profiles/*/overlay/rootfs/usr/lib/dracut/modules.d/ only reaches a UKI
# on the next IMAGE BUILD - the module lives in the image's overlay, and
# `bootstrap`/`configure` regenerate the UKI from the image, not from the
# working tree. That is correct behaviour and it makes a hook fix untestable
# for the length of an image build.
#
# But the UKI is generated by gen-efi inside the slot:
#
#   dracut --force --uefi --kver "$kernel_ver" \
#          --kernel-cmdline "$kernel_cmdline" "${uki_path}.tmp"
#   sign_efi_binary "${uki_path}.tmp"          # sbsign with the MOK keypair
#
# so for TESTING a module change, the module can be written into the slot and
# the UKI regenerated through exactly that path. The cmdline is taken from the
# UKI that is already there rather than regenerated, so the bad UKI differs
# from a good one in nothing but the module.
#
# THIS IS NOT SHIPPING. It writes into a live slot's ESP; the image still
# carries the old module, and an image rebuild is what makes the change real
# for users.
#
# Usage (from `build.sh test enter <slot> --`):
#     regen-uki.sh <slot> [<slot>]
#
# Prerequisites, and they are not all obvious:
#   * the corrected module files must ALREADY be in the slot at
#     /usr/lib/dracut/modules.d/99shanios/ - the harness does not put the host's
#     working tree in here, and `/home/builduser/build` does not exist inside a
#     slot's namespace. Pass them in by content:
#         base64 -w0 <file> | ... | base64 -d > /usr/lib/dracut/modules.d/99shanios/<name>
#   * AND VERIFY THE COPY LANDED. An earlier attempt copied from a path that
#     does not exist inside a slot, the `cp` failed, and dracut cheerfully
#     regenerated the UKI from the OLD module - a run that looked successful and
#     tested nothing.
#   * the ESP must be mounted (the slot mounts it at /boot/efi)
set -uo pipefail

slots=("$@")
[[ ${#slots[@]} -gt 0 ]] || slots=(green)

for SLOT in "${slots[@]}"; do
    M=/usr/lib/dracut/modules.d/99shanios
    ESP=/boot/efi
    UKI="$ESP/EFI/shanios/shanios-$SLOT.efi"
    KV=$(ls /usr/lib/modules/ 2>/dev/null | head -1)

    echo "=== $SLOT ==="
    [[ -n $KV ]] || { echo "  no kernel in /usr/lib/modules"; continue; }
    [[ -f $UKI ]] || { echo "  no UKI at $UKI"; continue; }
    [[ -d $M ]]   || { echo "  no dracut module dir at $M"; continue; }

    # Refuse to regenerate from a module the caller believes it just fixed but
    # which is not there. The failure this prevents is silent and looks like a
    # successful run.
    if grep -q 'instmods vfat' "$M/module-setup.sh" 2>/dev/null; then
        echo "  module: has instmods vfat"
    else
        echo "  WARNING: $M/module-setup.sh has no 'instmods vfat'. Regenerating"
        echo "           now would test the OLD module and report success."
    fi

    # objcopy -O binary cannot write to /dev/stdout: it exits 0 and produces
    # nothing, so the pipeline reads as an empty cmdline rather than an error.
    t=$(mktemp) || { echo "  mktemp failed"; continue; }
    if ! objcopy -O binary --only-section=.cmdline "$UKI" "$t" 2>/dev/null || [[ ! -s $t ]]; then
        echo "  could not read .cmdline from the existing UKI"; rm -f "$t"; continue
    fi
    CMD=$(tr -d '\0' < "$t"); rm -f "$t"
    [[ -n $CMD ]] || { echo "  empty cmdline - refusing"; continue; }
    echo "  cmdline: ${CMD:0:90}..."

    before=$(stat -c %s "$UKI")
    if ! dracut --force --uefi --kver "$KV" --kernel-cmdline "$CMD" "${UKI}.tmp"; then
        echo "  dracut FAILED - the original UKI is untouched"; continue
    fi
    if ! sbsign --key /etc/secureboot/keys/MOK.key \
                --cert /etc/secureboot/keys/MOK.crt \
                "${UKI}.tmp" --output "${UKI}.tmp.signed"; then
        echo "  sbsign FAILED - the original UKI is untouched"; rm -f "${UKI}.tmp"; continue
    fi
    mv -f "${UKI}.tmp.signed" "$UKI"; rm -f "${UKI}.tmp"
    after=$(stat -c %s "$UKI")
    echo "  regenerated: ${before} -> ${after} bytes (delta $((after - before)))"
    echo "  NOTE: this is a test-only in-place rebuild; the image still carries the old module."
done